<section class="container page-heading"><span class="section-kicker">Aktivitas akun</span><div class="page-toolbar"><div><h1>Reservasi saya</h1><p>Lihat status sesi, tagihan, dan perkembangan pesanan foto Anda.</p></div><a class="btn btn-copper" href="<?= e(url('home')) ?>#paket">+ Buat Reservasi</a></div></section>
<section class="container pb-5"><div class="surface"><div class="table-wrap"><table class="table"><thead><tr><th>Kode / Paket</th><th>Jadwal sesi</th><th>Status reservasi</th><th>Pembayaran</th><th></th></tr></thead><tbody>
<?php foreach ($reservations as $item): $paid = (float) $item['total_terbayar']; $paymentStatus = $paid >= (float) $item['harga_paket_snapshot'] ? 'lunas' : ($paid > 0 ? 'dp' : ((int) $item['pembayaran_menunggu'] > 0 ? 'menunggu' : 'belum_bayar')); ?>
<tr><td><strong><?= e($item['kode_reservasi']) ?></strong><span class="subtext"><?= e($item['nama_paket']) ?></span></td><td><?= e(date_id($item['tanggal_sesi'])) ?><span class="subtext"><?= e(substr((string) $item['jam_sesi'],0,5)) ?> · <?= (int) $item['durasi_menit_snapshot'] ?> menit</span></td><td><span class="badge-status <?= e(status_class($item['status'])) ?>"><?= e(status_label($item['status'])) ?></span></td><td><span class="badge-status <?= e(status_class($paymentStatus)) ?>"><?= e(status_label($paymentStatus)) ?></span><span class="subtext"><?= money($paid) ?> / <?= money($item['harga_paket_snapshot']) ?></span></td><td class="text-end"><a class="btn btn-sm btn-outline-dark" href="<?= e(url('reservation',['id'=>$item['id_reservasi']])) ?>">Detail ↗</a></td></tr>
<?php endforeach; ?>
<?php if (!$reservations): ?><tr><td colspan="5"><div class="empty-state m-3"><div class="empty-symbol">▦</div><h3>Belum ada reservasi</h3><p>Pilih paket foto dan jadwal yang tersedia untuk memulai.</p><a class="btn btn-copper" href="<?= e(url('home')) ?>#paket">Lihat Paket</a></div></td></tr><?php endif; ?>
</tbody></table></div></div></section>
